 3	function getPreferredLanguage(acceptLanguageHeader: string | null): string {
 4	  if (!acceptLanguageHeader) {
 5	    return 'unknown';
 6	  }
 7	
 8	  const [firstLanguage] = acceptLanguageHeader.split(',');
 9	  return firstLanguage?.trim() || 'unknown';
10	}
