12	export default async function ThemePreference() {
13	  const cookieStore = await cookies();
14	  const headerStore = await headers();
15	
16	  const theme = cookieStore.get('theme')?.value ?? 'light';
17	  const preferredLanguage = getPreferredLanguage(
18	    headerStore.get('accept-language')
19	  );
